import json, sys

def trunc(s, n=400):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def summarize_content(content):
    if isinstance(content, str):
        return trunc(content)
    if isinstance(content, list):
        parts = []
        for block in content:
            if not isinstance(block, dict):
                parts.append(trunc(block, 200))
                continue
            btype = block.get('type')
            if btype == 'text':
                parts.append(f"[text] {trunc(block.get('text',''), 400)}")
            elif btype == 'tool_use':
                parts.append(f"[tool_use:{block.get('name')}] {trunc(block.get('input',''), 300)}")
            elif btype == 'tool_result':
                c = block.get('content')
                parts.append(f"[tool_result] {trunc(c, 300)}")
            elif btype == 'image':
                parts.append("[image omitted]")
            else:
                parts.append(f"[{btype}] {trunc(block, 200)}")
        return " || ".join(parts)
    return trunc(content, 400)

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception as e:
            print(f"PARSE_ERROR: {e}")
            continue
        typ = d.get('type')
        ts = d.get('timestamp')
        role = d.get('role') or d.get('userType')
        if typ == 'summary':
            print(f"--SUMMARY-- {trunc(d, 300)}")
            continue
        msg = d.get('message')
        content = None
        if isinstance(msg, dict):
            role = msg.get('role', role)
            content = msg.get('content')
        elif d.get('content') is not None:
            content = d.get('content')
        line_out = f"[{ts}] type={typ} role={role} sidechain={d.get('isSidechain')}"
        if content is not None:
            line_out += " :: " + summarize_content(content)
        print(line_out)

